Voici un exemple de code pour créer un bot Discord avec la commande "bannir" à l'aide de Discord.js v14 :

```javascript
// Importez les dépendances Discord.js
const { Client, GatewayIntentBits } = require('discord.js');

// Créez un nouveau client Discord
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Connectez le client au Discord
client.login('VOTRE_TOKEN_DISCORD');

// Écoutez les événements du client
client.on('ready', () => {
  console.log(`Bot en ligne avec l'ID ${client.user.id}`);
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  // Traitement de la commande "bannir"
  if (interaction.commandName === 'bannir') {
    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'Vous n'avez pas la permission de bannir les utilisateurs.',
        ephemeral: true,
      });
    }

    const member = interaction.mentions.members.first();
    if (!member) {
      return interaction.reply({
        content: 'Veuillez mentionner un utilisateur à bannir.',
        ephemeral: true,
      });
    }

    if (!member.bannable) {
      return interaction.reply({
        content: 'Je ne peux pas bannir cet utilisateur.',
        ephemeral: true,
      });
    }

    await interaction.member.guild.members.ban(member.user.id, { days: 0, reason: 'Commande "bannir"' });

    return interaction.reply({
      content: `${member.user} a été banni avec succès.`,
      ephemeral: false,
    });
  }
});
```

