    while (getline(inputFile, line)) { // lire chaque ligne du fichier
        lineNumber++;

        // convertir la ligne en petit majuscules pour la comparaison
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        size_t pos = 0;
        while ((pos = line.find(wordToSearch, pos)) != string::npos) { // trouver toutes les occurrences du mot dans la ligne
            wordCount++; // incrémenter le compteur
            pos++; // passer au caractère suivant
        }
